var urlInput = document.getElementById('url-input');
var aliasInput = document.getElementById('custom-alias');
var fieldset = document.getElementById('suggestions-fieldset');
var listEl = document.getElementById('suggestions-list');
var resultBox = document.getElementById('result-box');
var resultShortUrl = document.getElementById('result-short-url');
var resultTargetUrl = document.getElementById('result-target-url');
var lastNormalizedUrl = '';
var lastStateKey = '';

function hashString(input) {
  var h = 2166136261;
  for (var i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function slugifySegment(value, fallback) {
  var cleaned = value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 12)
    .replace(/-+$/g, '');
  return cleaned || fallback;
}

function parseHttpUrl(raw) {
  var trimmed = raw.trim();
  if (!trimmed) {
    return null;
  }
  try {
    var parsed = new URL(trimmed);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return null;
    }
    return parsed;
  } catch (err) {
    return null;
  }
}

function shortHash(input, length) {
  return hashString(input).toString(36).slice(0, length);
}

function buildFiveSuggestions(parsedUrl, customAliasSlug) {
  var hostParts = parsedUrl.hostname.replace(/^www\./i, '').split('.');
  var hostSlug = slugifySegment(hostParts[0] || 'site', 'site');
  var pathParts = parsedUrl.pathname.split('/').filter(Boolean);
  var lastPath = pathParts.length > 0 ? pathParts[pathParts.length - 1] : 'link';
  var pathSlug = slugifySegment(lastPath, 'link');

  if (customAliasSlug) {
    return [
      '/s/' + customAliasSlug,
      '/s/' + hostSlug + '-' + pathSlug,
      '/s/' + pathSlug + '-' + shortHash(parsedUrl.href + '#1', 4),
      '/s/' + hostSlug + '-' + shortHash(parsedUrl.href + '#2', 4),
      '/s/' + shortHash(parsedUrl.href + '#3', 6)
    ];
  }

  return [
    '/s/' + hostSlug + '-' + pathSlug,
    '/s/' + pathSlug + '-' + shortHash(parsedUrl.href + '#1', 4),
    '/s/' + hostSlug + '-' + shortHash(parsedUrl.href + '#2', 4),
    '/s/' + shortHash(parsedUrl.href + '#3', 6),
    '/s/go-' + shortHash(parsedUrl.href + '#4', 4)
  ];
}

function renderSuggestions(parsedUrl, customAliasSlug) {
  var suggestions = buildFiveSuggestions(parsedUrl, customAliasSlug);
  listEl.textContent = '';

  suggestions.forEach(function (shortPath, index) {
    var label = document.createElement('label');
    label.className = 'suggestion-option';

    var radio = document.createElement('input');
    radio.type = 'radio';
    radio.name = 'short_url';
    radio.value = shortPath;
    radio.required = true;
    if (index === 0) {
      radio.checked = true;
    }

    var codeSpan = document.createElement('span');
    codeSpan.className = 'suggestion-code';
    codeSpan.textContent = shortPath;

    label.appendChild(radio);
    label.appendChild(codeSpan);
    listEl.appendChild(label);
  });

  fieldset.hidden = false;
}

function getSelectedSuggestion() {
  var checked = listEl.querySelector('input[name="short_url"]:checked');
  return checked ? checked.value : '';
}

function updateSuggestionsFromInput() {
  urlInput.setCustomValidity('');
  if (aliasInput) {
    aliasInput.setCustomValidity('');
  }

  var rawAlias = aliasInput ? aliasInput.value.trim() : '';
  var customAliasSlug = rawAlias ? slugifySegment(rawAlias, '') : '';
  if (rawAlias && !customAliasSlug) {
    lastNormalizedUrl = '';
    lastStateKey = '';
    listEl.textContent = '';
    fieldset.hidden = true;
    resultBox.hidden = true;
    aliasInput.setCustomValidity('Custom alias must contain letters or numbers.');
    return null;
  }

  var raw = urlInput.value;
  if (!raw.trim()) {
    lastNormalizedUrl = '';
    lastStateKey = '';
    listEl.textContent = '';
    fieldset.hidden = true;
    resultBox.hidden = true;
    return null;
  }

  var parsed = parseHttpUrl(raw);
  if (!parsed) {
    lastNormalizedUrl = '';
    lastStateKey = '';
    listEl.textContent = '';
    fieldset.hidden = true;
    resultBox.hidden = true;
    if (urlInput.validity.valid) {
      urlInput.setCustomValidity('Please enter an http:// or https:// URL.');
    }
    return null;
  }

  var nextStateKey = parsed.href + '\n' + customAliasSlug;
  if (nextStateKey !== lastStateKey) {
    lastNormalizedUrl = parsed.href;
    lastStateKey = nextStateKey;
    renderSuggestions(parsed, customAliasSlug);
    resultBox.hidden = true;
  }
  return parsed;
}

urlInput.addEventListener('input', function () {
  updateSuggestionsFromInput();
});
if (aliasInput) {
  aliasInput.addEventListener('input', function () {
    updateSuggestionsFromInput();
  });
}

