}

var URLCtor = typeof URL === 'function' ? URL : parseUrlPolyfill;

function assertEqual(actual, expected, message) {
  if (actual !== expected) {
    throw new Error((message || 'Assertion failed') + ': expected ' + JSON.stringify(expected) + ', got ' + JSON.stringify(actual));
  }
}

function assertOk(value, message) {
  if (!value) {
    throw new Error(message || 'Expected truthy value');
  }
}

function createHarness() {
  var html = readIndexHtml();
  var scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/);
  assertOk(scriptMatch, 'Expected inline <script> in index.html');

  function makeElement(tagName, id) {
    var listeners = {};
    var el = {
      tagName: String(tagName || 'div').toUpperCase(),
      id: id || '',
      className: '',
      type: '',
      name: '',
      value: '',
      checked: false,
      required: false,
      hidden: Boolean(id && new RegExp('id="' + id + '"[^>]*\\bhidden\\b').test(html)),
      children: [],
      validationMessage: '',
      validity: { valid: true },
      setCustomValidity: function (msg) {
        this.validationMessage = msg;
      },
      appendChild: function (child) {
        this.children.push(child);
        return child;
      },
      addEventListener: function (event, handler) {
        listeners[event] = listeners[event] || [];
        listeners[event].push(handler);
      },
      dispatchEvent: function (event) {
        var handlers = listeners[event.type] || [];
