          if (input && (input.validationMessage || !input.validity.valid)) {
            return false;
          }
        }
        return true;
      }
    };

    Object.defineProperty(el, 'textContent', {
      get: function () {
        return this._text || '';
      },
      set: function (val) {
        this._text = String(val);
        if (val === '') {
