        }
      }
    });

    return el;
  }

  var ids = [
    'shorten-form',
    'url-input',
    'custom-alias',
    'suggestions-fieldset',
    'suggestions-list',
    'result-box',
    'result-short-url',
    'result-target-url'
  ];

